}
.cookie-editor-react .cookie-account-scope li:last-child{border:0}
.cookie-editor-react .cookie-account-scope li strong{font-weight:650;min-width:0}
.cookie-editor-react .cookie-account-scope li small{overflow-wrap:anywhere;min-width:0}
.cookie-editor-react .cookie-account-card.is-just-saved{
